import timeit

def _t():
    try:
        timeit.Timer(stmt=None)
    except ValueError:
        pass
    try:
        timeit.Timer(stmt='return')
    except SyntaxError:
        pass
    try:
        timeit.Timer(stmt='yield')
    except SyntaxError:
        pass
    try:
        timeit.Timer(stmt='yield from ()')
    except SyntaxError:
        pass
    try:
        timeit.Timer(stmt='break')
    except SyntaxError:
        pass
    try:
        timeit.Timer(stmt='continue')
    except SyntaxError:
        pass
    try:
        timeit.Timer(stmt='from timeit import *')
    except SyntaxError:
        pass
    try:
        timeit.Timer(stmt='  pass')
    except SyntaxError:
        pass
    try:
        timeit.Timer(setup='while False:\n  pass', stmt='  break')
    except SyntaxError:
        pass
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

